argv:
$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
Add-Type @"
using System;
using System.Runtime.InteropServices;
public static class W32FileDlg {
 [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
 [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd,int n);
}
"@
$dlg=[System.Windows.Automation.AutomationElement]::FromHandle([IntPtr]396086)
if($null -eq $dlg -or [string]$dlg.Current.ClassName -ne '#32770'){
  $desktop=[System.Windows.Automation.AutomationElement]::RootElement
  $wins=$desktop.FindAll([System.Windows.Automation.TreeScope]::Children,[System.Windows.Automation.Condition]::TrueCondition)
  $dlg=$null
  for($i=0;$i -lt $wins.Count;$i++){
    $w=$wins.Item($i)
    if([string]$w.Current.ClassName -eq '#32770' -and [string]$w.Current.Name -eq '開啟'){ $dlg=$w; break }
  }
}
if($null -eq $dlg){throw 'Open dialog not found'}
[W32FileDlg]::ShowWindow([IntPtr]$dlg.Current.NativeWindowHandle,9)|Out-Null
[W32FileDlg]::SetForegroundWindow([IntPtr]$dlg.Current.NativeWindowHandle)|Out-Null
$all=$dlg.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$out=@()
for($i=0;$i -lt $all.Count;$i++){
 $e=$all.Item($i)
 $ct=$e.Current.ControlType.ProgrammaticName
 if($ct -match 'Edit|ComboBox|Button'){
   $r=$e.Current.BoundingRectangle
   $out += [pscustomobject]@{
     type=$ct
     name=[string]$e.Current.Name
     aid=[string]$e.Current.AutomationId
     class=[string]$e.Current.ClassName
     focusable=[bool]$e.Current.IsKeyboardFocusable
     enabled=[bool]$e.Current.IsEnabled
     x=[string]$r.X;y=[string]$r.Y;w=[string]$r.Width;h=[string]$r.Height
   }
 }
}
[pscustomobject]@{dialog=[string]$dlg.Current.Name;controls=$out}|ConvertTo-Json -Depth 5 -Compress
